export const AUTOMATION_FORM_UPDATE_TOOL_NAME = "automation_form_update";

/**
 * Action discriminator generated by the SDK for the client-defined automation
 * form tool (`ClientAction_<tool-name>`). Keep this convention centralized.
 */
export const AUTOMATION_FORM_UPDATE_ACTION_KIND =
  `ClientAction_${AUTOMATION_FORM_UPDATE_TOOL_NAME}` as const;

/**
 * The capabilities feature flag the automation service advertises (see
 * `OpenHands/automation` PR #417) when server-backed automation drafts are
 * available. The setup form gates the persisted-draft flow on this so a
 * deployment that predates the endpoints falls back to client-only state.
 */
export const AUTOMATION_DRAFTS_FEATURE = "automationDrafts";

/**
 * The capabilities feature flag the automation service advertises when an
 * automation can run as a service account (`run_as_kind: "service"`,
 * `run_as_user_id` on create, `POST /v1/{id}/run-as`).
 */
export const SERVICE_ACCOUNT_RUN_AS_FEATURE = "serviceAccountRunAs";
